<?php
require_once __DIR__.'/bootstrap.php';$u=requireUser();$pdo=db();$stages=['sifarisler','istehsalat','cilalama','boyalama','anbar'];$priorities=['low','medium','high','urgent'];$roles=['istehsalat'=>'istehsalat_ustasi','cilalama'=>'cilalama_ustasi','boyalama'=>'boyalama_ustasi','anbar'=>'anbar_ustasi'];
try{
if($_SERVER['REQUEST_METHOD']==='GET'){$where=[];$args=[];if(!empty($_GET['search'])){$where[]='(t.title LIKE ? OR t.description LIKE ?)';$args[]='%'.$_GET['search'].'%';$args[]='%'.$_GET['search'].'%';}if(!empty($_GET['priority'])){$where[]='t.priority=?';$args[]=$_GET['priority'];}if(!empty($_GET['stage'])){$where[]='t.current_stage=?';$args[]=$_GET['stage'];}$q='SELECT t.*,c.name creator_name,a.name assigned_name FROM tasks t JOIN users c ON c.id=t.created_by LEFT JOIN users a ON a.id=t.assigned_to'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY t.updated_at DESC';$s=$pdo->prepare($q);$s->execute($args);jsonResponse(['tasks'=>$s->fetchAll()]);}
if($_SERVER['REQUEST_METHOD']==='POST'){requireManager($u);$title=trim((string)($_POST['title']??''));$priority=$_POST['priority']??'medium';if($title===''||!in_array($priority,$priorities,true))jsonResponse(['error'=>'Məlumatlar düzgün deyil'],422);$path=null;if(!empty($_FILES['image']['tmp_name'])){$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['image']['tmp_name']);$map=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($map[$mime])||$_FILES['image']['size']>5242880)jsonResponse(['error'=>'Şəkil 5MB-dan böyük ola bilməz'],422);if(!is_dir(UPLOAD_DIR))mkdir(UPLOAD_DIR,0755,true);$file=bin2hex(random_bytes(12)).'.'.$map[$mime];move_uploaded_file($_FILES['image']['tmp_name'],UPLOAD_DIR.$file);$path=UPLOAD_URL.$file;}$s=$pdo->prepare('INSERT INTO tasks(title,description,image_path,current_stage,priority,created_by,assigned_to) VALUES(?,?,?,?,?,?,?)');$s->execute([$title,$_POST['description']??null,$path,'sifarisler',$priority,$u['id'],$u['id']]);jsonResponse(['id'=>$pdo->lastInsertId()],201);}
if($_SERVER['REQUEST_METHOD']==='PUT'){$d=requestData();$id=(int)($d['id']??0);if(!$id)jsonResponse(['error'=>'Task id tələb olunur'],422);if($u['role']==='manager'&&array_intersect(['title','description','priority'],array_keys($d))){$fields=[];$values=[];foreach(['title','description','priority'] as $f)if(array_key_exists($f,$d)){$fields[]="$f=?";$values[]=$d[$f];}if(isset($d['priority'])&&!in_array($d['priority'],$priorities,true))jsonResponse(['error'=>'Prioritet düzgün deyil'],422);$values[]=$id;$s=$pdo->prepare('UPDATE tasks SET '.implode(',',$fields).' WHERE id=?');$s->execute($values);jsonResponse(['updated'=>true]);}$stage=$d['stage']??$d['current_stage']??'';if(!in_array($stage,$stages,true))jsonResponse(['error'=>'Stage düzgün deyil'],422);if($u['role']==='manager'){if(!isset($roles[$stage])){$s=$pdo->prepare("UPDATE tasks SET current_stage=?,target_stage=NULL,approval_status='active',assigned_to=? WHERE id=?");$s->execute([$stage,$u['id'],$id]);jsonResponse(['updated'=>true]);}$s=$pdo->prepare("UPDATE tasks SET target_stage=?,approval_status='pending_approval' WHERE id=? AND approval_status='active'");$s->execute([$stage,$id]);if($s->rowCount()){$n=$pdo->prepare("INSERT INTO notifications(task_id,target_role,message,type) VALUES(?,?,?,'approval_request')");$n->execute([$id,$roles[$stage],'Manager tapşırığı təsdiq üçün '.$stage.' mərhələsinə göndərdi']);}jsonResponse(['updated'=>true,'pending_approval'=>true]);}if(!isset($roles[$stage])||$u['role']!==$roles[$stage])jsonResponse(['error'=>'Bu mərhələ üçün icazəniz yoxdur'],403);$s=$pdo->prepare("UPDATE tasks SET target_stage=?,approval_status='pending_approval' WHERE id=? AND approval_status='active'");$s->execute([$stage,$id]);if($s->rowCount()){$n=$pdo->prepare("INSERT INTO notifications(task_id,target_role,message,type) VALUES(?,?,?,'approval_request')");$n->execute([$id,$roles[$stage],'Yeni mərhələ keçidi təsdiq gözləyir']);}jsonResponse(['updated'=>true,'pending_approval'=>true]);}
if($_SERVER['REQUEST_METHOD']==='DELETE'){requireManager($u);$d=requestData();$s=$pdo->prepare('DELETE FROM tasks WHERE id=?');$s->execute([(int)($d['id']??0)]);jsonResponse(['deleted'=>true]);}jsonResponse(['error'=>'Method not allowed'],405);
}catch(Throwable $e){error_log('tasks.php: '.$e->getMessage());jsonResponse(['error'=>'Sifariş əməliyyatı alınmadı'],500);}
